[
 {"name":"The Dunes Resort","aliases":"The Dunes Resort|Dunes Resort|Douglas Dunes Resort|The Douglas Dunes","city":"saugatuck","description":"A landmark LGBTQ+ resort and entertainment complex operating since 1981, with motel rooms, cottages, pool, dance club, cabaret and multiple bars. It is both the area's most explicit queer stay and its principal permanent nightlife anchor.","vibe":"iconic all-in-one LGBTQ resort joining pool days, cabaret, bars and late dancing","tags":"social,party,mixed","hours":"Front desk and entertainment operate daily in season; the complex publishes bar and event schedules separately.","link":"https://dunesresort.com/","location":"333 South Blue Star Highway, Douglas, MI 49406, USA","lat":42.637900,"lng":-86.210650,"arrival":"Summer weekends and major themed events pressure parking, check-in and club entry; complete room and event bookings separately.","best":"Best for travellers wanting the queer social centre on site, especially Pride, holiday and programmed summer weekends.","crowd":"LGBTQ+ adults across generations, with gay men strongly represented alongside lesbians, trans guests, couples and allies.","dress":"Resort casual and swimwear by day; expressive clubwear or announced themes at night, with no assumption that themes are compulsory.","inclusion":"The resort explicitly describes four decades of welcoming LGBTQ+ travellers and centres queer freedom in its current mission.","basis":"Direct first-party LGBTQ+ identity, history and active entertainment evidence; stronger than a generic welcoming-directory label.","class":"LGBTQ+ resort and entertainment complex","coords":"Mapbox Geocoding v5 exact-address match checked 2026-08-27.","sources":["https://dunesresort.com/"]},
 {"name":"The Kirby Hotel","aliases":"The Kirby Hotel|Kirby Hotel|The Kirby","city":"saugatuck","description":"A small historic boutique hotel in Douglas with individually designed rooms, garden space and an on-site restaurant. Its intimate scale suits couples who want queer-owned hospitality without the full party-resort environment.","vibe":"intimate historic boutique stay with garden calm and owner-led hospitality","tags":"cozy,cultural,relax","hours":"Arrival and restaurant service follow current reservation instructions; confirm late check-in directly.","link":"https://thekirbyhotel.com/","location":"294 West Center Street, Douglas, MI 49406, USA","lat":42.643965,"lng":-86.207668,"arrival":"The small room count makes advance booking important; send arrival and accessibility needs directly rather than relying on platform notes.","best":"Best for couples wanting a quiet Douglas base close to The Dunes while retaining a more private boutique atmosphere.","crowd":"Queer couples and solo travellers mix with culinary visitors, wedding guests and Art Coast weekenders.","dress":"Relaxed boutique-hotel clothing; the restaurant suits neat smart-casual dress.","inclusion":"The hotel's official contact page explicitly states that the property is proudly LGBT owned and operated.","basis":"Current first-party LGBT ownership statement paired with the active property and exact address.","class":"Independent historic boutique hotel","coords":"Mapbox Geocoding v5 exact-address match checked 2026-08-27.","sources":["https://thekirbyhotel.com/contact/"]},
 {"name":"Lake Shore Resort","aliases":"Lake Shore Resort|Lakeshore Resort|Lake Shore Resort Saugatuck","city":"saugatuck","description":"A small Lake Michigan resort with water views from every room, heated pool, breakfast, bikes, kayaks, yoga, trails and sunset decks. The official destination organisation identifies it among the area's LGBTQ-owned lodging businesses.","vibe":"peaceful queer-owned lakefront resort focused on sunsets, nature and active downtime","tags":"relax,cozy,cultural","hours":"Main resort season is May-October; check-in 16:00 and check-out 11:00; cottage winter dates differ.","link":"https://www.lakeshoreresortsaugatuck.com/","location":"2885 Lakeshore Drive, Fennville, MI 49408, USA","lat":42.626770,"lng":-86.227220,"arrival":"High demand, deposits and multi-night summer minimums make early booking essential; the lake-bluff layout should be discussed for mobility needs.","best":"Best for couples prioritising water, pool, trails and quiet sunsets over immediate bar access.","crowd":"LGBTQ+ couples and friends mix with nature travellers and returning Midwest resort guests; children under 13 are not accommodated.","dress":"Lakeside casual, swimwear and walking layers; practical footwear matters on trails and waterfront stairs.","inclusion":"Saugatuck's official destination guide lists Lake Shore among LGBTQ-owned accommodation, while the hotel itself welcomes a broad audience.","basis":"Current first-party operation plus official destination-marketing evidence of LGBTQ ownership.","class":"Seasonal independent lakefront resort","coords":"Mapbox Geocoding v5 exact-address match checked 2026-08-27.","sources":["https://www.lakeshoreresortsaugatuck.com/","https://saugatuck.com/why-the-art-coast-is-a-must-visit-destination-for-the-lgbtq-traveler/"]},
 {"name":"Hidden Garden Cottages & Suites","aliases":"Hidden Garden Cottages & Suites|Hidden Garden Cottages|Hidden Gardens Cottages","city":"saugatuck","description":"Four private romantic cottages and suites for two in downtown Saugatuck, with fireplaces, whirlpools, kitchenettes and in-room continental breakfast. The two male owners live on site and operate the property personally.","vibe":"private gay-owned downtown cottages designed for quiet couples and car-free wandering","tags":"cozy,relax,cultural","hours":"Open year-round; arrival follows direct booking instructions and the owners' on-site service.","link":"https://www.hiddengardencottages.com/","location":"247 Butler Street, Saugatuck, MI 49453, USA","lat":42.656450,"lng":-86.203845,"arrival":"Only four units exist, so reserve early and confirm stairs, parking and late arrival before travel.","best":"Best for couples wanting privacy, breakfast on their own schedule and immediate downtown walking access.","crowd":"Queer couples are strongly represented within a welcoming adult romantic-stay audience.","dress":"Private cottage and casual downtown clothing; there are no formal shared public rooms.","inclusion":"The owners document a two-man operation and long gay-inclusive history; a current specialist lodging source classifies the property as gay owned.","basis":"First-party ownership/history and current gay-owned lodging classification, not inferred from city reputation alone.","class":"Gay-owned boutique cottages and suites","coords":"Officially published GPS and Mapbox exact-address match checked 2026-08-27.","sources":["https://www.hiddengardencottages.com/","https://www.hiddengardencottages.com/history.html","https://purpleroofs.com/listing/hidden-garden-cottages/"]},

 {"name":"Kimpton Hotel Monaco Salt Lake City","aliases":"Kimpton Hotel Monaco Salt Lake City|Hotel Monaco Salt Lake City|Kimpton Monaco SLC","city":"salt_lake_city","description":"A design-forward downtown Kimpton in a restored 1920s building with Bambara restaurant, Vault cocktail lounge, social hour, pet-friendly policies and easy walking access to central Pride activity.","vibe":"bold historic boutique hotel with social-hour warmth and explicit Pride welcome","tags":"luxury,social,cultural","hours":"Reception and fitness operate 24 hours; restaurants, lounge and social hour follow separate schedules.","link":"https://www.monaco-saltlakecity.com/","location":"15 West 200 South, Salt Lake City, UT 84101, USA","lat":40.764698,"lng":-111.891900,"arrival":"Downtown events affect valet and lobby flow; reserve adapted rooms and parking directly.","best":"Best for Pride visitors wanting an explicit LGBTQ welcome, central theatres and a polished social boutique base.","crowd":"Queer couples and solo travellers mix with business guests, pet owners, theatre audiences and city-break visitors.","dress":"Design-hotel casual; Bambara and Vault suit smart-casual without a restrictive appearance rule.","inclusion":"The hotel maintains a dedicated LGBTQ+ welcome and Pride page and explicitly positions itself as a Pride home base.","basis":"Direct current first-party LGBTQ+ hotel statement and official Pride proximity information.","class":"Upscale historic Kimpton boutique hotel","coords":"Mapbox Geocoding v5 exact-address match checked 2026-08-27.","sources":["https://www.monaco-saltlakecity.com/hotels-downtown-salt-lake-city/pride/","https://www.monaco-saltlakecity.com/"]},
 {"name":"Asher Adams, Autograph Collection","aliases":"Asher Adams, Autograph Collection|Asher Adams Hotel|Asher Adams","city":"salt_lake_city","description":"A 225-room hotel built into the restored Union Pacific Depot, with dramatic Grand Hall, multiple bars and restaurants, rail-inspired design and immediate Delta Center access.","vibe":"grand restored-railway design hotel with destination bars and downtown event energy","tags":"luxury,cultural,social","hours":"Reception and guest service operate daily; restaurants and bars keep their own current hours.","link":"https://www.marriott.com/en-us/hotels/slcau-asher-adams-autograph-collection/overview/","location":"2 South 400 West, Salt Lake City, UT 84101, USA","lat":40.769289,"lng":-111.902923,"arrival":"Arena events can congest the forecourt and public Grand Hall; reserve parking and room access needs in advance.","best":"Best for design-conscious queer travellers who want Delta Center access, memorable architecture and social spaces on site.","crowd":"LGBTQ+ city visitors mix with concert and sports guests, design travellers and restaurant patrons.","dress":"Polished city casual suits the Grand Hall; bars lean smart-casual on event nights.","inclusion":"Visit Salt Lake's current dedicated LGBTQ+ city guide selects Asher Adams in its where-to-stay section.","basis":"Current official destination LGBTQ editorial selection plus live Marriott property data; no queer ownership is claimed.","class":"Upscale Autograph Collection landmark hotel","coords":"Mapbox Geocoding v5 exact-address match checked 2026-08-27.","sources":["https://www.visitsaltlake.com/articles/post/out-in-salt-lake-city-an-lgbtq-guide-to-utahs-unexpectedly-cool-capital/","https://www.marriott.com/en-us/hotels/slcau-asher-adams-autograph-collection/overview/"]},
 {"name":"Hilton Salt Lake City Center","aliases":"Hilton Salt Lake City Center|Hilton Salt Lake City Centre|Hilton SLC Center","city":"salt_lake_city","description":"A large downtown convention hotel with indoor pool, fitness, restaurant and direct access to the Salt Palace area. Hilton previously documented it as the premier lodging sponsor and kickoff host for Utah Pride.","vibe":"full-service convention hotel with documented Pride partnership and central transport access","tags":"social,mixed,luxury","hours":"Reception and guest services operate 24 hours; dining, pool and fitness follow property schedules.","link":"https://www.hilton.com/en/hotels/slccchh-hilton-salt-lake-city-center/","location":"255 South West Temple, Salt Lake City, UT 84101, USA","lat":40.763821,"lng":-111.893542,"arrival":"Convention and festival dates create lobby, lift and parking peaks; confirm accessible room features directly.","best":"Best for large-event access, full-service facilities and travellers who value a documented Pride partnership.","crowd":"Queer Pride guests mix with convention delegates, families, business travellers and tour groups.","dress":"Mainstream hotel casual; conferences and restaurants may lean smart-casual.","inclusion":"Hilton publicly documented the property as Utah Pride's premier lodging sponsor and event host.","basis":"First-party corporate Pride partnership evidence combined with current hotel operation; partnership year should not be presented as ownership.","class":"Large full-service downtown Hilton","coords":"Mapbox Geocoding v5 exact-address match checked 2026-08-27.","sources":["https://stories.hilton.com/destination-spotlight/stay-with-pride-stay-with-hilton-unforgettable-celebrations-await-lgbtq-travelers","https://www.hilton.com/en/hotels/slccchh-hilton-salt-lake-city-center/"]},
 {"name":"Little America Hotel Salt Lake City","aliases":"Little America Hotel Salt Lake City|Little America Hotel|Little America SLC","city":"salt_lake_city","description":"A long-established Main Street hotel with garden courtyard, indoor and outdoor pools, restaurants and broad room categories, offering a resort-like footprint close to downtown transit.","vibe":"classic large city hotel with pools, gardens and practical downtown access","tags":"relax,mixed,cultural","hours":"Reception operates 24 hours; pools, restaurants and other facilities publish separate schedules.","link":"https://saltlake.littleamerica.com/","location":"500 South Main Street, Salt Lake City, UT 84101, USA","lat":40.758650,"lng":-111.891100,"arrival":"The large property has multiple room areas and parking routes; confirm the exact building and accessible path before arrival.","best":"Best for travellers wanting pools, on-site dining and TRAX access while remaining outside the loudest club blocks.","crowd":"Queer visitors mix with families, road travellers, business groups and long-time regional guests.","dress":"General hotel casual; restaurants suit neat casual attire.","inclusion":"Visit Utah includes Little America in its official LGBTQ Salt Lake City travel guidance.","basis":"State destination LGBTQ editorial inclusion plus current first-party hotel operation; no queer ownership or specialist certification is asserted.","class":"Large independent full-service city hotel","coords":"Exact-address map position cross-checked for 500 South Main, 2026-08-27.","sources":["https://www.visitutah.com/articles/salt-lake-city-rainbow-colors-fly-high","https://saltlake.littleamerica.com/"]},

 {"name":"The Hollis Halifax - a DoubleTree Suites by Hilton","aliases":"The Hollis Halifax - a DoubleTree Suites by Hilton|The Hollis Halifax DoubleTree Suites|The Hollis Halifax","city":"halifax","description":"An all-suite downtown Hilton near the waterfront and convention centre, with indoor pool, fitness and restaurant. Discover Halifax includes it on the city's current 2SLGBTQIA+ allied-business accommodation list.","vibe":"central all-suite hotel with documented local ally status and waterfront convenience","tags":"mixed,social,cultural","hours":"Reception and guest services operate 24 hours; pool, fitness and dining use separate schedules.","link":"https://www.hilton.com/en/hotels/yhzdhdt-the-hollis-halifax-a-doubletree-suites-by-hilton/","location":"1649 Hollis Street, Halifax, NS B3J 1V8, Canada","lat":44.646820,"lng":-63.572190,"arrival":"Convention and cruise dates crowd nearby streets; reserve parking and adapted suites in advance.","best":"Best for Pride and downtown visitors wanting an explicitly listed local ally with suite space.","crowd":"2SLGBTQIA+ visitors mix with business travellers, families, cruise guests and convention groups.","dress":"Mainstream city-hotel casual; restaurant evenings are informal smart-casual.","inclusion":"Discover Halifax lists the property among businesses with self-identified ally, Pride-sponsor or queer-event evidence.","basis":"Current official destination allied-business listing paired with current Hilton property information.","class":"Full-service all-suite DoubleTree hotel","coords":"Mapbox Geocoding v5 exact-address match checked 2026-08-27.","sources":["https://discoverhalifaxns.com/plan/lgbthalifaxresources/lgbt-allied-businesses/","https://www.hilton.com/en/hotels/yhzdhdt-the-hollis-halifax-a-doubletree-suites-by-hilton/"]},
 {"name":"The Sutton Place Hotel Halifax","aliases":"The Sutton Place Hotel Halifax|Sutton Place Halifax|The Sutton Halifax","city":"halifax","description":"A luxury downtown hotel attached to the convention-centre district, with individually styled rooms, Chop Steakhouse, valet parking and a seasonal outdoor hot tub.","vibe":"polished downtown luxury with designer rooms and immediate arena-convention access","tags":"luxury,cultural,mixed","hours":"Reception operates 24 hours; restaurant, fitness and seasonal hot-tub hours vary.","link":"https://www.suttonplace.com/halifax","location":"1700 Grafton Street, Halifax, NS B3J 2C4, Canada","lat":44.646686,"lng":-63.575616,"arrival":"Arena and convention traffic can pressure valet and Grafton Street; reserve parking and access needs directly.","best":"Best for couples prioritising luxury, central nightlife walking and an on-site dinner.","crowd":"Queer couples and solo guests mix with event visitors, business travellers and luxury city-break guests.","dress":"Polished city casual; Chop leans smart-casual.","inclusion":"The current property policy explicitly welcomes guests of all sexual orientations and gender identities.","basis":"Property-specific LGBTQ-friendly policy in a current lodging record plus live first-party hotel operation.","class":"Five-star downtown luxury hotel","coords":"Mapbox Geocoding v5 exact-address match checked 2026-08-27.","sources":["https://www.hotels.com/ho1635833088/the-sutton-place-hotel-halifax-halifax-canada/","https://www.suttonplace.com/halifax"]},
 {"name":"Atlantica Hotel Halifax","aliases":"Atlantica Hotel Halifax|Atlantica Halifax","city":"halifax","description":"A full-service hotel across from the Halifax Common with indoor pool, restaurant, pet-friendly rooms and useful access to the North End and downtown by foot or short ride.","vibe":"relaxed Common-side full-service hotel balancing neighbourhood access and indoor-pool downtime","tags":"relax,mixed,social","hours":"Reception operates 24 hours; pool, restaurant and parking follow current property schedules.","link":"https://www.atlanticahotelhalifax.com/","location":"1980 Robie Street, Halifax, NS B3H 3G5, Canada","lat":44.651700,"lng":-63.590200,"arrival":"Event weekends pressure surface parking and elevators; discuss adapted rooms and pet needs before arrival.","best":"Best for travellers wanting Halifax Common, North End access and a calmer base outside the waterfront core.","crowd":"2SLGBTQIA+ guests mix with families, hospital visitors, sports groups and road travellers.","dress":"Uncomplicated hotel casual.","inclusion":"Hotels.com's current Halifax LGBTQIA-welcoming collection includes Atlantica; the hotel is not claimed as queer-owned.","basis":"Current inclusion-labelled destination catalogue paired with active first-party property details.","class":"Independent full-service city hotel","coords":"Exact-address map position cross-checked for 1980 Robie Street, 2026-08-27.","sources":["https://www.hotels.com/de1643770-th21/lgbtq-welcoming-hotels-halifax-and-vicinity-nova-scotia/","https://www.atlanticahotelhalifax.com/"]},
 {"name":"The Westin Nova Scotian","aliases":"The Westin Nova Scotian|Westin Nova Scotian|The Westin Halifax","city":"halifax","description":"A landmark railway-era waterfront hotel beside Halifax station and the Seaport, with indoor pool, fitness and restaurant. Its southern location is convenient for arrivals and waterfront walking.","vibe":"historic railway hotel with harbour access, full facilities and classic public rooms","tags":"luxury,cultural,relax","hours":"Reception operates 24 hours; pool, fitness and dining use separate schedules.","link":"https://www.marriott.com/en-us/hotels/yhzwi-the-westin-nova-scotian/overview/","location":"1181 Hollis Street, Halifax, NS B3H 2P6, Canada","lat":44.640000,"lng":-63.569800,"arrival":"Rail, cruise and event traffic affect the driveway; reserve parking and accessible room configuration directly.","best":"Best for railway convenience, Seaport markets and a quieter waterfront edge while remaining walkable to queer venues.","crowd":"Queer couples and visitors mix with rail passengers, conferences, families and heritage-hotel guests.","dress":"City casual; restaurant and event rooms become smart-casual.","inclusion":"The property appears in current LGBTQIA-welcoming Halifax accommodation catalogues; no ownership claim is made.","basis":"Current inclusion-labelled lodging evidence plus active first-party Marriott hotel data.","class":"Four-star historic full-service Westin","coords":"Exact-address map position cross-checked for 1181 Hollis Street, 2026-08-27.","sources":["https://www.hotels.com/de1643770-th21/lgbtq-welcoming-hotels-halifax-and-vicinity-nova-scotia/","https://www.marriott.com/en-us/hotels/yhzwi-the-westin-nova-scotian/overview/"]},

 {"name":"Rand Tower Hotel, Minneapolis, a Tribute Portfolio Hotel","aliases":"Rand Tower Hotel, Minneapolis, a Tribute Portfolio Hotel|Rand Tower Hotel|Rand Tower Minneapolis","city":"minneapolis","description":"An Art Deco downtown tower with design-led rooms, Bar Rufus and a central skyway location. Its 2026 Pride & Joy package included Pride perks and direct Twin Cities Pride festival information.","vibe":"Art Deco downtown boutique hotel with an explicit Pride package and cocktail-bar polish","tags":"luxury,cultural,social","hours":"Reception operates 24 hours; restaurant, bar, fitness and valet follow current schedules.","link":"https://www.marriott.com/en-us/hotels/msptr-rand-tower-hotel-minneapolis-a-tribute-portfolio-hotel/overview/","location":"527 Marquette Avenue, Minneapolis, MN 55402, USA","lat":44.977333,"lng":-93.269650,"arrival":"Downtown events and valet demand create peaks; request adapted rooms and exact parking guidance before travel.","best":"Best for Pride weekend, architecture and a central boutique stay close to the Hennepin queer circuit.","crowd":"Queer Pride guests mix with design travellers, business visitors and downtown event audiences.","dress":"Polished city casual; Bar Rufus suits smart-casual.","inclusion":"The hotel marketed a dedicated 2026 Pride & Joy package with Pride-linked benefits.","basis":"Current first-party Marriott Pride offer and live property data; no queer ownership claim.","class":"Upscale Art Deco Tribute Portfolio hotel","coords":"Mapbox Geocoding v5 exact-address match checked 2026-08-27.","sources":["https://www.marriott.com/offers/pride-and-joy-offer-OFF-223339/MSPTR-msptr-rand-tower-hotel-minneapolis-a-tribute-portfolio-hotel","https://www.marriott.com/en-us/hotels/msptr-rand-tower-hotel-minneapolis-a-tribute-portfolio-hotel/overview/"]},
 {"name":"Hotel Emery","aliases":"Hotel Emery|Emery, Autograph Collection|Emery Hotel Minneapolis","city":"minneapolis","description":"A downtown Autograph Collection hotel with dramatic bank-hall lobby, Spyhouse coffee, Giulia restaurant and skyway access. Its June 2026 Travel with Pride offer donated per occupied night to QUEERSPACE Collective.","vibe":"grand-bank-hall design hotel tying an explicit Pride stay to local queer-youth support","tags":"luxury,cultural,social","hours":"Reception operates 24 hours; café, restaurant and fitness keep separate schedules.","link":"https://www.hotelemery.com/","location":"215 South 4th Street, Minneapolis, MN 55401, USA","lat":44.978190,"lng":-93.266849,"arrival":"Business-day skyway and event traffic can crowd the lobby; reserve parking and access details in advance.","best":"Best for travellers wanting design, dining and a documented stay-linked contribution to local LGBTQ+ youth.","crowd":"Queer couples and Pride visitors mix with business travellers, diners and design-focused city guests.","dress":"Modern city casual; Giulia leans smart-casual.","inclusion":"The hotel's 2026 Travel with Pride offer donated $10 per stayed night to Minneapolis-based QUEERSPACE Collective.","basis":"Direct first-party Pride campaign with named local LGBTQ+ beneficiary, plus current hotel operation.","class":"Upscale Autograph Collection design hotel","coords":"Mapbox Geocoding v5 exact-address match checked 2026-08-27.","sources":["https://www.hotelemery.com/offers/travel-with-pride/","https://www.hotelemery.com/"]},
 {"name":"Sheraton Minneapolis Downtown Convention Center","aliases":"Sheraton Minneapolis Downtown Convention Center|Sheraton Minneapolis Downtown|Millennium Minneapolis","city":"minneapolis","description":"A convention-oriented hotel a few blocks from Loring Park with pool, fitness and broad room inventory. Twin Cities Pride's current visitor page identifies it as an accommodation partner and provides Pride-weekend market codes.","vibe":"practical convention hotel with direct Pride accommodation partnership and Loring Park access","tags":"mixed,social,relax","hours":"Reception operates 24 hours; pool, fitness, dining and parking follow current schedules.","link":"https://www.marriott.com/en-us/hotels/mspdt-sheraton-minneapolis-downtown-convention-center/overview/","location":"1313 Nicollet Mall, Minneapolis, MN 55403, USA","lat":44.970498,"lng":-93.277010,"arrival":"Pride and convention weekends produce check-in and garage peaks; book through the valid festival route and confirm room needs.","best":"Best for short walks to Loring Park Pride and travellers prioritising practical full-service facilities.","crowd":"LGBTQ+ festival guests mix with convention delegates, families and group travellers.","dress":"General city-hotel casual.","inclusion":"Twin Cities Pride lists the hotel in official accommodation guidance with Pride weekend discount codes.","basis":"Direct current organiser accommodation partnership paired with active first-party Marriott property information.","class":"Large full-service convention hotel","coords":"Mapbox Geocoding v5 exact-address match checked 2026-08-27.","sources":["https://tcpride.org/plan-your-visit/","https://www.marriott.com/en-us/hotels/mspdt-sheraton-minneapolis-downtown-convention-center/overview/"]},
 {"name":"The Lofton Hotel Minneapolis, Tapestry Collection by Hilton","aliases":"The Lofton Hotel Minneapolis, Tapestry Collection by Hilton|The Lofton Hotel Minneapolis|Lofton Hotel Minneapolis|Loews Minneapolis Hotel","city":"minneapolis","description":"A downtown lifestyle hotel opposite Target Center with a lobby bar, restaurant and event-focused location near Hennepin nightlife. Twin Cities Pride includes it in the official accommodation section.","vibe":"arena-side lifestyle hotel with Pride organiser recognition and immediate downtown nightlife access","tags":"luxury,social,cultural","hours":"Reception operates 24 hours; restaurant, bar and fitness follow current schedules.","link":"https://www.hilton.com/en/hotels/mspupup-the-lofton-hotel-minneapolis/","location":"601 North 1st Avenue, Minneapolis, MN 55403, USA","lat":44.978783,"lng":-93.274893,"arrival":"Arena events congest First Avenue and valet service; confirm event timing, parking and adapted rooms.","best":"Best for concerts, Target Center and a short walk to The Saloon and Gay 90's.","crowd":"Queer Pride and nightlife visitors mix with concert guests, sports fans and business travellers.","dress":"Contemporary city casual; event nights become more polished or fan-led.","inclusion":"Twin Cities Pride names The Lofton in its official accommodation guidance.","basis":"Current Pride organiser listing and live first-party Hilton property information; no ownership claim.","class":"Upscale Tapestry Collection lifestyle hotel","coords":"Mapbox Geocoding v5 exact-address match checked 2026-08-27.","sources":["https://tcpride.org/plan-your-visit/","https://www.hilton.com/en/hotels/mspupup-the-lofton-hotel-minneapolis/"]},

 {"name":"Hotel Indigo Cardiff","aliases":"Hotel Indigo Cardiff|Indigo Cardiff","city":"cardiff","description":"A 122-room Welsh-design boutique hotel hidden in Dominions Arcade, with rooftop restaurant and terrace views near Cardiff Castle and the compact queer nightlife circuit.","vibe":"Welsh-themed central boutique hotel with rooftop views and a documented Pride partnership","tags":"luxury,cultural,social","hours":"Reception operates 24 hours; rooftop restaurant, bar and fitness follow separate schedules.","link":"https://www.ihg.com/hotelindigo/hotels/gb/en/cardiff/cdfin/hoteldetail","location":"Dominions Arcade, Queen Street, Cardiff CF10 2AR, United Kingdom","lat":51.482136,"lng":-3.175130,"arrival":"The arcade entrance and pedestrian centre require clear luggage and parking instructions; confirm step-free routing directly.","best":"Best for Pride, castle access and travellers wanting Welsh design with the queer circuit in walking range.","crowd":"LGBTQ+ couples and Pride guests mix with design travellers, rugby visitors and city-break groups.","dress":"Contemporary city casual; the rooftop suits smart-casual.","inclusion":"Visit Wales identifies the hotel as LGBT+ friendly and documents its Pride Cymru discounted-rate partnership.","basis":"Official national destination LGBTQ lodging guide plus current first-party IHG hotel data.","class":"Four-star Hotel Indigo boutique property","coords":"Mapbox address-level match to Queen Street/Dominions Arcade checked 2026-08-27.","sources":["https://www.visitwales.com/places-stay/great-lgbt-friendly-places-stay-wales","https://www.ihg.com/hotelindigo/hotels/gb/en/cardiff/cdfin/hoteldetail"]},
