 {"name":"Park Plaza Cardiff","aliases":"Park Plaza Cardiff|Cardiff Park Plaza","city":"cardiff","description":"A 129-room central hotel with Laguna restaurant, indoor pool and spa near Cardiff Castle, Churchill Way and the main LGBTQ+ bars and clubs.","vibe":"calm spa hotel a short walk from late queer nightlife and city landmarks","tags":"luxury,relax,cultural","hours":"Reception operates 24 hours; spa, pool, fitness and restaurant use separate booking and opening schedules.","link":"https://www.parkplazacardiff.com/","location":"Greyfriars Road, Cardiff CF10 3AL, United Kingdom","lat":51.483326,"lng":-3.176879,"arrival":"Weekend events and spa demand create parking and check-in peaks; reserve treatments and adapted rooms directly.","best":"Best for couples balancing nightlife walking with pool, spa and quieter on-site downtime.","crowd":"LGBTQ+ couples and solo guests mix with spa visitors, business travellers and event weekends.","dress":"Relaxed hotel clothing; spa attire in facilities and smart-casual in Laguna.","inclusion":"Visit Wales lists Park Plaza in its LGBT+ friendly accommodation guide; TravelGay actively approves the property.","basis":"Two current specialist/official inclusion sources paired with live first-party hotel data.","class":"Four-star city spa hotel","coords":"Mapbox Geocoding v5 exact-street match checked 2026-08-27.","sources":["https://www.visitwales.com/places-stay/great-lgbt-friendly-places-stay-wales","https://www.travelgay.com/gay-cardiff-hotels","https://www.parkplazacardiff.com/"]},
 {"name":"Ty Rosa Boutique B&B","aliases":"Ty Rosa Boutique B&B|Ty Rosa|Ty Rosa Boutique Gay B&B","city":"cardiff","description":"A small gay-run Grangetown guest house whose name means Pink House, offering individually styled rooms, lounge space and easy rail or bus access to the centre and Cardiff Bay.","vibe":"personal gay-run guest house offering a quieter alternative to central chain hotels","tags":"cozy,cultural,relax","hours":"Arrival and breakfast follow direct booking instructions; confirm late check-in before travel.","link":"https://www.visitcardiff.com/highlights/ty-rosa/","location":"118 Clive Street, Cardiff CF11 7JE, United Kingdom","lat":51.467200,"lng":-3.189300,"arrival":"The small property requires advance arrival coordination; confirm stairs, parking and the currently bookable room inventory.","best":"Best for queer travellers wanting owner-led hospitality, neighbourhood calm and straightforward access to the Bay and centre.","crowd":"Gay and broader LGBTQ+ couples and solo visitors mix with welcoming general guests in a small B&B setting.","dress":"Informal guest-house clothing; no formal public-space expectation.","inclusion":"Visit Cardiff explicitly describes Ty Rosa as gay-run and welcoming regardless of orientation.","basis":"Current official destination listing with direct gay-run status; stronger than generic legal non-discrimination alone.","class":"Gay-run boutique bed and breakfast","coords":"Exact address cross-checked with public lodging records; map position verified for Clive Street 2026-08-27.","sources":["https://www.visitcardiff.com/highlights/ty-rosa/"]}
]
$qa_hotels$) h(name text,aliases text,city text,description text,vibe text,tags text,hours text,link text,location text,lat double precision,lng double precision,arrival text,best text,crowd text,dress text,inclusion text,basis text,class text,coords text,sources jsonb)
), hotels as (
 select h.*,string_to_array(replace(h.tags,'party','relax'),',')::text[] approved_tags,
   jsonb_build_object('queue_wait',arrival,'best_nights',best,'crowd_mix',crowd,'dress_code',dress,'staff_inclusivity',inclusion,'inclusion_basis',basis,'hotel_class',class,'coordinate_source',coords,'source_urls',sources,'research_status','current_lgbtq_evidence_plus_official_property_source','updated_at','2026-08-27T00:00:00Z') intel
 from raw_hotels h
), updated as (
 update public.places p set name=h.name,type='hotel',description=h.description,vibe=h.vibe,vibe_tags=h.approved_tags,hours=h.hours,link=h.link,location=h.location,lat=h.lat,lng=h.lng,venue_intel=coalesce(p.venue_intel,'{}'::jsonb)||h.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now())
 from hotels h
 where lower(trim(p.city))=h.city and lower(trim(p.name)) in(select lower(trim(alias_name)) from unnest(string_to_array(h.aliases,'|')) alias_name)
 returning p.id
)
insert into public.places(name,city,type,description,vibe,vibe_tags,hours,link,location,lat,lng,venue_intel,seo_indexable,seo_quality_status,updated_at)
select h.name,h.city,'hotel',h.description,h.vibe,h.approved_tags,h.hours,h.link,h.location,h.lat,h.lng,h.intel,true,'approved',timezone('utc',now())
from hotels h
where not exists(select 1 from public.places p where lower(trim(p.city))=h.city and lower(trim(p.name)) in(select lower(trim(alias_name)) from unnest(string_to_array(h.aliases,'|')) alias_name));

select public.qa_refresh_city_seo_status(slug)
from (values('saugatuck'),('salt_lake_city'),('halifax'),('minneapolis'),('cardiff')) v(slug)
where to_regprocedure('public.qa_refresh_city_seo_status(text)') is not null;

commit;

select lower(trim(city)) city,count(*) filter(where type='hotel') batch_hotel_count,
       count(*) filter(where type='hotel')=4 target_exactly_four
from public.places
where lower(trim(city)) in('saugatuck','salt_lake_city','halifax','minneapolis','cardiff')
  and lower(trim(name)) in(
    'the dunes resort','the kirby hotel','lake shore resort','hidden garden cottages & suites',
    'kimpton hotel monaco salt lake city','asher adams, autograph collection','hilton salt lake city center','little america hotel salt lake city',
    'the hollis halifax - a doubletree suites by hilton','the sutton place hotel halifax','atlantica hotel halifax','the westin nova scotian',
    'rand tower hotel, minneapolis, a tribute portfolio hotel','hotel emery','sheraton minneapolis downtown convention center','the lofton hotel minneapolis, tapestry collection by hilton',
    'hotel indigo cardiff','clayton hotel cardiff','park plaza cardiff','ty rosa boutique b&b'
  )
group by lower(trim(city)) order by lower(trim(city));
